using UnityEngine;
using UnityEditor;
using LWS.TruckSports.Editor;
namespace LWS.TruckTerrierRacing.Editor {
public static class TerrierTunnelAuthoring {
 public static void Install(TerrierMatch m){var root=m.course.finish;for(int i=root.childCount-1;i>=0;i--)UnityEngine.Object.DestroyImmediate(root.GetChild(i).gameObject);root.localRotation=Quaternion.identity;root.localScale=Vector3.one;var dark=AssetDatabase.LoadAssetAtPath<Material>("Assets/TruckTerrierRacing/Materials/Barrier graphite.mat");var amber=AssetDatabase.LoadAssetAtPath<Material>("Assets/TruckTerrierRacing/Materials/Tunnel gold.mat");var contact=AssetDatabase.LoadAssetAtPath<PhysicsMaterial>("Assets/TruckTerrierRacing/Materials/Barrier contact.asset");float half=TerrierRules.TunnelHalfWidth,width=(42-half*2)*.5f;for(int side=-1;side<=1;side+=2){var wall=SportsEventAuthoring.Box("Solid finish barrier",new Vector3(side*(half+width*.5f),3,TerrierRules.TunnelDepth*.5f),new Vector3(width,6,TerrierRules.TunnelDepth),dark,contact,root);wall.AddComponent<TerrierFinishWall>();SportsEventAuthoring.Box("Tunnel side trim",new Vector3(side*(half+.08f),TerrierRules.TunnelHeight*.5f,-.04f),new Vector3(.16f,TerrierRules.TunnelHeight,.08f),amber,null,root);}var lintel=SportsEventAuthoring.Box("Solid finish lintel",new Vector3(0,(6+TerrierRules.TunnelHeight)*.5f,TerrierRules.TunnelDepth*.5f),new Vector3(half*2,6-TerrierRules.TunnelHeight,TerrierRules.TunnelDepth),dark,contact,root);lintel.AddComponent<TerrierFinishWall>();SportsEventAuthoring.Box("Finish tunnel roof trim",new Vector3(0,TerrierRules.TunnelHeight+.08f,-.04f),new Vector3(half*2+.32f,.16f,.08f),amber,null,root);var sign=SportsEventAuthoring.Label("Finish hole sign","THROUGH HERE",Vector3.zero,.3f,Color.white);sign.transform.SetParent(root,false);sign.transform.localPosition=new Vector3(0,4.4f,-.1f);sign.transform.localRotation=Quaternion.identity;}
}
}
